{
  "findings": [
    {
      "check_id": "CKV_GCP_28",
      "title": "Ensure that Cloud Storage bucket is not anonymously or publicly accessible",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "The bucket does not have any access control configuration, which may allow anonymous or public access."
    },
    {
      "check_id": "CKV_GCP_29",
      "title": "Ensure that Cloud Storage buckets have uniform bucket-level access enabled",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "The bucket does not have uniform bucket-level access enabled, which may lead to inconsistent access control."
    },
    {
      "check_id": "CKV_GCP_62",
      "title": "Bucket should log access",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "The bucket does not have access logging enabled, which may make it difficult to track and monitor access to the bucket."
    },
    {
      "check_id": "CKV_GCP_114",
      "title": "Ensure public access prevention is enforced on Cloud Storage bucket",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "The bucket does not have public access prevention enforced, which may allow public access to the bucket."
    }
  ],
  "patched_code": "resource \"google_storage_bucket\" \"compliance_storage\" {\n  name     = \"${var.project_id}-digital-asset-trading-platform-compliance\"\n  location = var.region\n  versioning {\n    enabled = true\n  }\n  lifecycle_rule {\n    condition {\n      age = 2555\n    }\n    action {\n      type = \"Delete\"\n    }\n  }\n  uniform_bucket_level_access = true\n  logging {\n    log_bucket = \"${var.project_id}-digital-asset-trading-platform-compliance-logs\"\n  }\n  public_access_prevention = \"enforced\"\n}",
  "fix_summary": "Enabled uniform bucket-level access, access logging, and public access prevention on the Cloud Storage bucket."
}
